  const data = JSON.parse(e.responses[0].examples[0].data);
  const paramUrl = e.url.replace(/\{([^}]+)}/g, ":$1"); // :param form
  const braceKey = "GET " + e.url; // {param} form
  paginating.push({ id:e.id, paramUrl, braceKey, resultsKey: Array.isArray(data)?null:findKey(data), doc:e.documentationUrl });
}
function findKey(d){ for(const[k,v] of Object.entries(d)) if(Array.isArray(v)) return k; }

